insert into flashcards (id, week, track, front, back, source) values
  ('w1-adults-001', 1, 'adults', 'What does it mean to invest?', 'Investing is putting your money to work so it can grow instead of sitting idle. You give your money a job: to create more money over time.', 'textbook p5'),
  ('w1-adults-002', 1, 'adults', 'Compounding', 'The process by which your money makes more money, and that money then makes even more money. Because it snowballs, starting early gives time to work in your favor.', 'textbook p5'),
  ('w1-adults-003', 1, 'adults', 'Why does starting early matter?', 'Time is an investor''s best friend. The earlier you start, the longer compounding can grow your money toward long-term goals like a home, a business, or retirement.', 'textbook p5'),
  ('w1-adults-004', 1, 'adults', 'Stock', 'A security representing proportionate ownership in a company. Buying a stock makes you a shareholder with a claim on part of the company''s assets and earnings.', 'textbook p6, p21'),
  ('w1-adults-005', 1, 'adults', 'Dividend', 'A payment a company makes to shareholders, usually in cash or additional shares. Not all companies pay them; those that do usually pay on a regular schedule.', 'textbook p6'),
  ('w1-adults-006', 1, 'adults', 'Bond', 'A loan you give to a company or government. In return they repay you with interest after a set period, called the maturity date. Bonds are debt, not ownership.', 'textbook p6'),
  ('w1-adults-007', 1, 'adults', 'Mutual fund', 'An investment vehicle that pools money from many investors into a professionally managed portfolio of stocks, bonds, or other securities, making diversification easy.', 'textbook p6'),
  ('w1-adults-008', 1, 'adults', 'ETF (Exchange-Traded Fund)', 'A basket of securities that tracks an index, sector, commodity, or other asset. Like a mutual fund, but it trades on an exchange throughout the day like an individual stock.', 'textbook p7'),
  ('w1-adults-009', 1, 'adults', 'Capital gains vs. capital loss', 'A capital gain is the profit when you sell an asset for more than you paid; a capital loss is when you sell for less. Gains held one year or less are short-term; more than a year are long-term, and each is taxed differently.', 'textbook p7'),
  ('w1-adults-010', 1, 'adults', 'Bull market vs. bear market', 'A bull market is when prices are rising or expected to rise; a bear market is when prices are falling or expected to fall.', 'textbook p7'),
  ('w1-adults-011', 1, 'adults', 'Portfolio', 'The full collection of financial assets you own: stocks, bonds, mutual funds, ETFs, and other investments.', 'textbook p7'),
  ('w1-adults-012', 1, 'adults', 'Risk tolerance', 'The degree of uncertainty or potential financial loss an investor is willing to accept in exchange for a potential reward.', 'textbook p7'),
  ('w1-adults-013', 1, 'adults', 'Asset allocation', 'Dividing your portfolio among asset categories such as stocks, bonds, and cash to balance risk and return based on your goals and risk tolerance.', 'textbook p7'),
  ('w1-adults-014', 1, 'adults', 'What is the stock market?', 'A public marketplace where shares of publicly traded companies are bought and sold. It is not one physical place but a network of exchanges and brokers that connects buyers and sellers.', 'textbook p11'),
  ('w1-adults-015', 1, 'adults', 'IPO (Initial Public Offering)', 'The process by which a private company first issues stock to the public to raise funds. After the IPO, its shares can be traded on an exchange.', 'textbook p11'),
  ('w1-adults-016', 1, 'adults', 'What drives stock prices?', 'Supply and demand. If more people want to buy than sell, shares become scarce and the price rises; if more want to sell than buy, the excess supply pushes the price down.', 'textbook p11'),
  ('w1-adults-017', 1, 'adults', 'Ticker symbol', 'A unique series of letters that identifies a company''s stock on an exchange (for example, MSFT for Microsoft). It allows fast, precise trading with no confusion.', 'textbook p12'),
  ('w1-adults-018', 1, 'adults', 'Market index', 'A snapshot of a portion of the stock market used to describe the market and compare investment returns.', 'textbook p13'),
  ('w1-adults-019', 1, 'adults', 'Dow Jones Industrial Average (DJIA)', 'A price-weighted index of 30 large U.S. companies across various sectors, representing about 25% of total U.S. market capitalization. One of the oldest and most-followed indices.', 'textbook p14'),
  ('w1-adults-020', 1, 'adults', 'S&P 500', 'A market-capitalization-weighted index of the 500 largest U.S. public companies, widely seen as the best gauge of large-cap U.S. equities and about 80% of U.S. market cap.', 'textbook p14'),
  ('w1-adults-021', 1, 'adults', 'NASDAQ Composite', 'A market-cap-weighted index heavily weighted toward the technology sector, including many U.S. and international companies such as Apple, Microsoft, Amazon, and Alphabet.', 'textbook p14'),
  ('w1-adults-022', 1, 'adults', 'The three market trends', 'Uptrend (bull): higher highs and higher lows. Downtrend (bear): lower highs and lower lows. Sideways (consolidation/range-bound): no clear direction. No trend lasts forever.', 'textbook p15-19'),
  ('w1-adults-023', 1, 'adults', 'Common vs. preferred stock', 'Common stockholders get voting rights and dividends but are last in line if the company is liquidated. Preferred stockholders get dividends first and a higher claim on assets, but usually no voting rights.', 'textbook p21-23'),
  ('w2-adults-001', 2, 'adults', 'What is technical analysis?', 'A method of evaluating securities by studying price action and charts. Its core idea is that history tends to repeat itself in market behavior, so past patterns can hint at future moves.', 'textbook p93, p138'),
  ('w2-adults-002', 2, 'adults', 'Candlestick', 'A chart mark showing a security''s price action over one time period. Its body spans the open-to-close range, and its wicks (shadows) reach the high and low prices of that period.', 'textbook p94'),
  ('w2-adults-003', 2, 'adults', 'Candlestick body: green vs. red', 'If the close is above the open, the body is bullish (green/white): buyers dominated. If the close is below the open, the body is bearish (red/black): sellers dominated.', 'textbook p94'),
  ('w2-adults-004', 2, 'adults', 'Candlestick wicks (shadows)', 'The thin lines above and below the body. The upper wick reaches the period''s high, the lower wick reaches the low. They show the price extremes and the tug-of-war between buyers and sellers.', 'textbook p94'),
  ('w2-adults-005', 2, 'adults', 'Long vs. short candlestick body', 'A long body signals strong buying or selling pressure and an intense battle. A short body suggests low volatility and a more balanced market.', 'textbook p94'),
  ('w2-adults-006', 2, 'adults', 'Line chart vs. bar chart', 'A line chart connects closing prices for a simple trend overview. A bar chart adds detail: a vertical line shows the high-low range, with small dashes for the open and close.', 'textbook p95'),
  ('w2-adults-007', 2, 'adults', 'Heikin-Ashi candles', 'A candlestick variation that uses averaged prices (open, close, high, low of prior candles) to smooth out noise and make the prevailing trend easier to see. ''Heikin-Ashi'' means ''average bar.''', 'textbook p96-97'),
  ('w2-adults-008', 2, 'adults', 'Support and resistance', 'Price levels where buying (support) or selling (resistance) pressure is strong enough to pause, reverse, or consolidate price. Support acts like a floor; resistance acts like a ceiling.', 'textbook p98-99'),
  ('w2-adults-009', 2, 'adults', 'Trendlines', 'Lines drawn to connect consecutive higher lows in an uptrend or consecutive lower highs in a downtrend. They frame potential entry and exit points and show trend strength.', 'textbook p101'),
  ('w2-adults-010', 2, 'adults', 'Trendline angle', 'The steepness of a trendline hints at the trend''s strength and sustainability. A very steep line may be hard to sustain; a moderate slope is often more durable.', 'textbook p102'),
  ('w2-adults-011', 2, 'adults', 'Trendline breakout vs. pullback', 'A breakout is when price closes decisively through a trendline, potentially starting a new move. A pullback is a bounce back to the line, which can offer an entry in the trend''s direction.', 'textbook p103'),
  ('w2-adults-012', 2, 'adults', 'Multiple timeframe analysis', 'Reviewing the same security across several timeframes (for example weekly, daily, hourly) so a signal on one chart is confirmed by the broader context of another.', 'textbook p100'),
  ('w2-adults-013', 2, 'adults', 'Volume', 'The total number of shares traded in a period. It measures activity and liquidity; a surge in volume often accompanies significant price moves and helps confirm them.', 'textbook p69, p117'),
  ('w2-adults-014', 2, 'adults', 'Why confirm moves with volume?', 'Volume shows the strength behind a price move. A breakout or trend backed by rising volume is more trustworthy than one on weak volume.', 'textbook p117'),
  ('w2-adults-015', 2, 'adults', 'Higher highs and higher lows', 'The defining structure of an uptrend: each peak is higher than the last and each pullback low is also higher than the last. The reverse (lower highs, lower lows) defines a downtrend.', 'textbook p15'),
  ('w2-adults-016', 2, 'adults', 'What does a candlestick chart reveal?', 'It shows the ongoing battle between buyers and sellers over each period and gives clues about momentum, volatility, and possible future price movement.', 'textbook p94-95'),
  ('w2-adults-017', 2, 'adults', 'Consolidation (range-bound market)', 'A sideways phase where price trades between support and resistance without a clear trend, often before a breakout in either direction.', 'textbook p18, p99'),
  ('w2-adults-018', 2, 'adults', 'Candlestick patterns (overview)', 'Groups of candles read together for signals: doji, hammer, engulfing, and harami among others. They can hint at reversals, continuations, or market uncertainty.', 'textbook p94'),
  ('w3-adults-001', 3, 'adults', 'Chart patterns', 'Recognizable shapes formed by price on a chart that suggest likely future moves. They fall into continuation patterns (trend resumes) and reversal patterns (trend changes).', 'textbook p105'),
  ('w3-adults-002', 3, 'adults', 'Head and shoulders pattern', 'A reversal pattern of three peaks: a higher center peak (head) between two lower peaks (shoulders). It typically signals a trend change, often bearish, confirmed on a break of the neckline with volume.', 'textbook p107, p138'),
  ('w3-adults-003', 3, 'adults', 'Double top and double bottom', 'Reversal patterns where price tests a level twice and fails. A double top signals a potential move down; a double bottom signals a potential move up.', 'textbook p138'),
  ('w3-adults-004', 3, 'adults', 'How is a chart-pattern breakout confirmed?', 'Primarily by increased volume on the breakout, which adds validity that the move is real rather than a false signal.', 'textbook p138'),
  ('w3-adults-005', 3, 'adults', 'Wedge pattern', 'A consolidation pattern formed by two converging trendlines. It suggests a pause before price breaks out of the narrowing range.', 'textbook p138'),
  ('w3-adults-006', 3, 'adults', 'Moving average', 'An indicator that smooths price data into the average price over a set period, clarifying trend direction and marking potential support or resistance.', 'textbook p115, p117'),
  ('w3-adults-007', 3, 'adults', 'SMA vs. EMA', 'A Simple Moving Average weights all periods equally. An Exponential Moving Average weights recent prices more heavily, so it reacts faster to price changes.', 'textbook p118'),
  ('w3-adults-008', 3, 'adults', 'Golden cross vs. death cross', 'A golden cross is when a shorter moving average crosses above a longer one (bullish). A death cross is when the shorter crosses below the longer (bearish). Both are lagging signals.', 'textbook p118'),
  ('w3-adults-009', 3, 'adults', 'MACD', 'Moving Average Convergence Divergence, a trend-following momentum indicator that measures the relationship between two moving averages and signals potential reversals or continuations.', 'textbook p115'),
  ('w3-adults-010', 3, 'adults', 'RSI (Relative Strength Index)', 'An oscillator measuring the speed and change of price moves. Above 70 is generally considered overbought; below 30 is generally considered oversold.', 'textbook p116'),
  ('w3-adults-011', 3, 'adults', 'Stochastic Oscillator', 'An oscillator comparing a closing price to its recent range. Readings above 80 suggest overbought conditions and below 20 suggest oversold.', 'textbook p116, p138'),
  ('w3-adults-012', 3, 'adults', 'Bollinger Bands', 'A moving average plus two standard-deviation bands. Contracting bands suggest low volatility; expanding bands suggest higher volatility and possible reversals.', 'textbook p116, p138'),
  ('w3-adults-013', 3, 'adults', 'ADX (Average Directional Index)', 'A trend-strength indicator. A rising ADX means the trend is strong; a falling ADX means price is consolidating. It measures strength, not direction.', 'textbook p115, p138'),
  ('w3-adults-014', 3, 'adults', 'What is fundamental analysis?', 'Evaluating a stock by analyzing the company''s financial statements, industry trends, and macroeconomic factors to estimate its intrinsic value and growth potential.', 'textbook p73-74'),
  ('w3-adults-015', 3, 'adults', 'The three financial statements', 'Income statement (revenues, expenses, net income over a period), balance sheet (assets, liabilities, equity at a point in time), and cash flow statement (cash in and out from operating, investing, and financing).', 'textbook p76-77'),
  ('w3-adults-016', 3, 'adults', 'P/E ratio (Price-to-Earnings)', 'The stock''s current price divided by its earnings per share. It gauges the market''s valuation of a company relative to its earnings and enables comparison with peers.', 'textbook p69, p89'),
  ('w3-adults-017', 3, 'adults', 'EPS (Earnings per Share)', 'The portion of a company''s profit assigned to each outstanding share of common stock. It is a core indicator of profitability.', 'textbook p69, p183'),
  ('w3-adults-018', 3, 'adults', 'Debt-to-equity ratio', 'Total debt divided by shareholders'' equity. It measures how much of a company''s financing comes from debt versus equity; higher means more leverage and potential risk.', 'textbook p78'),
  ('w3-adults-019', 3, 'adults', 'Current ratio', 'Current assets divided by current liabilities. A liquidity measure of the company''s ability to meet short-term obligations; higher generally means better short-term liquidity.', 'textbook p78'),
  ('w3-adults-020', 3, 'adults', 'Growth vs. value vs. income stocks', 'Growth stocks are expected to grow faster than average, earning returns mainly through price appreciation. Value stocks look underpriced versus intrinsic value. Income stocks pay steady dividends.', 'textbook p23'),
  ('w4-adults-001', 4, 'adults', 'What are options?', 'Derivative contracts giving the right, but not the obligation, to buy or sell an underlying asset at a set strike price within a set time. The two main types are calls and puts.', 'textbook p141'),
  ('w4-adults-002', 4, 'adults', 'Call option', 'Gives the holder the right to buy the underlying asset at the strike price before expiration. Traders buy calls when they expect the price to rise (bullish).', 'textbook p141, p143'),
  ('w4-adults-003', 4, 'adults', 'Put option', 'Gives the holder the right to sell the underlying asset at the strike price before expiration. Traders buy puts when they expect the price to fall (bearish).', 'textbook p141, p143'),
  ('w4-adults-004', 4, 'adults', 'Strike price', 'The predetermined price at which the underlying asset can be bought (call) or sold (put) under the option contract.', 'textbook p142'),
  ('w4-adults-005', 4, 'adults', 'Expiration date', 'The date the option contract expires. After it, the option is no longer valid.', 'textbook p142'),
  ('w4-adults-006', 4, 'adults', 'Premium', 'The price paid for an option contract. It reflects the option''s intrinsic value plus its time value.', 'textbook p142'),
  ('w4-adults-007', 4, 'adults', 'In-the-money (ITM)', 'A call is ITM when the asset''s price is above the strike; a put is ITM when the asset''s price is below the strike. ITM options have intrinsic value.', 'textbook p142'),
  ('w4-adults-008', 4, 'adults', 'Out-of-the-money (OTM)', 'A call is OTM when the asset''s price is below the strike; a put is OTM when the asset''s price is above the strike. OTM options have no intrinsic value.', 'textbook p142'),
  ('w4-adults-009', 4, 'adults', 'Leverage in options', 'Options let a trader control a larger position with less capital than buying the asset outright, which can amplify gains (and losses).', 'textbook p142'),
  ('w4-adults-010', 4, 'adults', 'Limited risk when buying options', 'The most a buyer can lose is the premium paid. If the option expires worthless, only that premium is lost.', 'textbook p143'),
  ('w4-adults-011', 4, 'adults', 'Why trade options?', 'For leverage, flexibility, risk management (hedging), and the ability to profit from up or down moves. Options can be used to speculate, hedge, or generate income.', 'textbook p142'),
  ('w4-adults-012', 4, 'adults', 'Directional strategies', 'Option strategies that profit from an expected price direction, such as buying calls for a bullish view or buying puts for a bearish view.', 'textbook p146'),
  ('w4-adults-013', 4, 'adults', 'Volatility strategies', 'Strategies designed to profit from big moves regardless of direction, such as a long straddle or long strangle. They benefit when volatility rises sharply.', 'textbook p146'),
  ('w4-adults-014', 4, 'adults', 'Protective put', 'Buying a put on stock you own to insure against a decline, protecting your holdings from potential losses like insurance.', 'textbook p161, p207'),
  ('w4-adults-015', 4, 'adults', 'Covered call', 'Selling a call against stock you own to generate income while holding the shares, best suited to a range-bound or mildly bullish market.', 'textbook p161'),
  ('w4-adults-016', 4, 'adults', 'Cash-secured put', 'Selling a put while holding enough cash to buy the shares if assigned. It aims to generate income while waiting to acquire a stock at a discount.', 'textbook p161'),
  ('w4-adults-017', 4, 'adults', 'Choosing calls vs. puts', 'Buy calls with a bullish outlook to profit from a rise; buy puts with a bearish outlook to profit from a fall. The choice follows your market view and strategy.', 'textbook p144'),
  ('w4-adults-018', 4, 'adults', 'Key risk of buying options', 'If the underlying does not move past the strike by expiration, the option can expire worthless and the full premium is lost.', 'textbook p143'),
  ('w5-adults-001', 5, 'adults', 'What is risk management?', 'Identifying, assessing, and mitigating potential risks to protect your capital and reach your goals. It reduces, but never eliminates, risk.', 'textbook p163-164'),
  ('w5-adults-002', 5, 'adults', 'Risk assessment', 'Evaluating your risk tolerance using your financial situation, goals, time horizon, age, income, and emotional resilience to decide how much risk suits you.', 'textbook p164-165'),
  ('w5-adults-003', 5, 'adults', 'Diversification', 'Spreading investments across different asset classes, sectors, and regions so a loss in one holding has less impact on the whole portfolio.', 'textbook p164, p167'),
  ('w5-adults-004', 5, 'adults', 'Position sizing', 'Deciding how much capital to allocate to each investment so no single position dominates the portfolio. It is about finding the right balance between risk and reward.', 'textbook p164, p169'),
  ('w5-adults-005', 5, 'adults', 'Fixed-dollar position sizing', 'Allocating the same set dollar amount to each position (for example $1,000 per stock) regardless of the stock''s price or volatility.', 'textbook p169'),
  ('w5-adults-006', 5, 'adults', 'Percentage-of-portfolio sizing', 'Allocating a fixed percentage of the portfolio''s total value to each position (for example 5% per stock), so size scales with the portfolio.', 'textbook p169'),
  ('w5-adults-007', 5, 'adults', 'Risk-based position sizing', 'Sizing each position by its inherent risk, using factors like volatility and price history; more capital to lower-risk positions, less to higher-risk ones.', 'textbook p169'),
  ('w5-adults-008', 5, 'adults', 'Risk-return tradeoff', 'The principle that higher potential returns generally come with higher risk. Be wary of anything promising high returns with little or no risk.', 'textbook p164'),
  ('w5-adults-009', 5, 'adults', 'Stop-loss order', 'An instruction to sell a security if it reaches a preset price, limiting the loss on a position if the trade moves against you.', 'textbook p164, p182'),
  ('w5-adults-010', 5, 'adults', 'Asset allocation vs. diversification', 'Asset allocation is how you split capital among asset classes based on risk tolerance and goals; diversification spreads within and across those classes to reduce single-investment risk.', 'textbook p164, p167'),
  ('w5-adults-011', 5, 'adults', 'Regular portfolio review and rebalancing', 'Periodically checking the portfolio and buying or selling to restore target allocations, since winners drift larger than planned over time.', 'textbook p167'),
  ('w5-adults-012', 5, 'adults', 'Emotional resilience in investing', 'The ability to handle market volatility without panic. Recognizing that fluctuations are normal helps you stay invested and stick to your strategy.', 'textbook p165'),
  ('w5-adults-013', 5, 'adults', 'Sector diversification', 'Spreading investments across sectors like technology, healthcare, finance, consumer goods, and energy so gains in some can offset losses in others.', 'textbook p167'),
  ('w5-adults-014', 5, 'adults', 'Size diversification', 'Holding small-, mid-, and large-cap companies, which behave differently: small-caps offer more growth potential but higher volatility.', 'textbook p167'),
  ('w5-adults-015', 5, 'adults', 'Pyramiding', 'Adding to a winning position as the trade moves in your favor, building size on strength to maximize profits.', 'textbook p170'),
  ('w5-adults-016', 5, 'adults', 'Anti-Martingale sizing', 'Increasing position size after a winning trade and reducing it after a loss, aiming to press winning streaks while limiting drawdowns.', 'textbook p170'),
  ('w5-adults-017', 5, 'adults', 'Kelly Criterion', 'A mathematical formula that recommends a position size based on the probability of success and the reward-to-risk ratio, used to optimize sizing.', 'textbook p170'),
  ('w5-adults-018', 5, 'adults', 'Why practice in a simulator first?', 'Paper trading lets you rehearse strategies and build discipline without risking real money before committing capital.', 'textbook p146, p171'),
  ('w6-adults-001', 6, 'adults', 'Brokerage account', 'An account that lets you buy and sell securities. Opening one is typically the first step to start investing in stocks and options.', 'textbook p174'),
  ('w6-adults-002', 6, 'adults', 'How do you choose a broker?', 'Compare trading costs, ease of use, customer support, investment options, and account types, using each brokerage''s site plus reviews and comparisons.', 'textbook p174-175'),
  ('w6-adults-003', 6, 'adults', 'Account setup information', 'Opening an account generally requires personal and financial details: name, address, Social Security number, employment, and questions about your experience and goals to gauge suitability.', 'textbook p173-174'),
  ('w6-adults-004', 6, 'adults', 'Market order', 'An order to buy or sell at the current market price. It usually fills quickly, but the exact fill price can move, especially in volatile markets.', 'textbook p181'),
  ('w6-adults-005', 6, 'adults', 'Limit order', 'An order to buy or sell at a specific price or better. A buy limit fills at the limit or lower; a sell limit fills at the limit or higher. It guarantees price but not execution.', 'textbook p181'),
  ('w6-adults-006', 6, 'adults', 'Stop order (stop-loss)', 'An order to buy or sell once a security reaches a set stop price. When the stop price is hit, the stop order becomes a market order.', 'textbook p182'),
  ('w6-adults-007', 6, 'adults', 'Steps to place a trade', 'Log in, find the security, choose buy or sell, specify order details (order type, quantity, duration), review and confirm, then monitor the order status.', 'textbook p181'),
  ('w6-adults-008', 6, 'adults', 'Bid, ask, and spread', 'The bid is the highest price a buyer will pay; the ask is the lowest a seller will accept. The gap between them is the bid-ask spread; a narrow spread signals a more liquid market.', 'textbook p69, p183'),
  ('w6-adults-009', 6, 'adults', '52-week high/low', 'The highest and lowest prices a stock has traded over the past 52 weeks, giving a sense of its range and volatility.', 'textbook p69, p184'),
  ('w6-adults-010', 6, 'adults', 'Beta', 'A measure of a stock''s volatility relative to the overall market. Beta above 1 means more volatile than the market; below 1 means less volatile.', 'textbook p184'),
  ('w6-adults-011', 6, 'adults', 'Market capitalization', 'The total market value of a company''s outstanding shares, calculated as current share price times shares outstanding. It sorts stocks into large-, mid-, and small-cap.', 'textbook p69, p184'),
  ('w6-adults-012', 6, 'adults', 'Traditional IRA vs. Roth IRA', 'A Traditional IRA may give a tax deduction now with earnings taxed at withdrawal. A Roth IRA is funded with after-tax dollars, and qualified withdrawals in retirement are tax-free.', 'textbook p191'),
  ('w6-adults-013', 6, 'adults', '401(k) plan', 'An employer-sponsored retirement account with often tax-deductible, tax-deferred contributions. Many employers match up to a percentage of salary, boosting growth over time.', 'textbook p191'),
  ('w6-adults-014', 6, 'adults', '529 plan', 'An education savings account offering tax-free growth and tax-free withdrawals for qualified education expenses.', 'textbook p191'),
  ('w6-adults-015', 6, 'adults', 'Short-term vs. long-term capital gains', 'Gains on assets held one year or less are taxed as ordinary income (10-37%). Gains held more than a year get lower long-term rates (0%, 15%, or 20% depending on bracket).', 'textbook p189'),
  ('w6-adults-016', 6, 'adults', 'Form 10-K vs. Form 10-Q', 'The 10-K is a company''s audited annual report with comprehensive financials. The 10-Q is a less-detailed, unaudited quarterly report that updates financial position through the year.', 'textbook p185-188'),
  ('w6-adults-017', 6, 'adults', 'Form 8-K', 'A filing companies use to report significant events shareholders should know about, such as earnings announcements or major business developments.', 'textbook p186'),
  ('w6-adults-018', 6, 'adults', 'Record-keeping for investing', 'Keep trade confirmations, brokerage statements, and year-end tax documents, organized by account, and monitor performance over time to evaluate your strategy.', 'textbook p188'),
  ('w6-adults-019', 6, 'adults', 'Paper trading', 'Practicing trades in a simulated environment with no real money, to build skills and confidence before risking real capital.', 'textbook p146, p171'),
  ('w6-adults-020', 6, 'adults', 'Stock dashboard', 'A brokerage''s overview of a stock showing current price, open, bid/ask, volume, P/E, EPS, market cap, dividend yield, 52-week high/low, news, and charts.', 'textbook p183-184'),
  ('w1-teens-001', 1, 'teens', 'Why invest instead of just saving?', 'Saving keeps your money safe but flat. Investing puts your money to work so it can grow. Over years, that difference is huge.', 'workbook ch1; textbook p5'),
  ('w1-teens-002', 1, 'teens', 'Compounding', 'Your money earns money, then that new money earns money too. It snowballs. That''s why time plus compounding is your biggest advantage.', 'workbook ch1; textbook p5'),
  ('w1-teens-003', 1, 'teens', 'Does starting early really matter?', 'Yes. Starting early beats starting with a lot. A small amount invested young has more time to compound than a big amount invested later.', 'workbook ch1'),
  ('w1-teens-004', 1, 'teens', 'What is a stock?', 'A share of ownership in a company. Buy one share of Apple and you literally own a tiny slice of Apple.', 'workbook pre-course A1; textbook p21'),
  ('w1-teens-005', 1, 'teens', 'Dividend', 'A cash (or share) payment some companies send shareholders just for owning the stock, usually every quarter. Not every company pays one.', 'textbook p6'),
  ('w1-teens-006', 1, 'teens', 'Bond vs. stock', 'A stock is ownership. A bond is a loan you make to a company or government that they pay back with interest. Owning vs. lending.', 'textbook p6'),
  ('w1-teens-007', 1, 'teens', 'ETF', 'A single investment that holds a whole basket of stocks and trades like one stock. Buy one ETF and you instantly own a little of many companies.', 'textbook p7'),
  ('w1-teens-008', 1, 'teens', 'Diversification', 'Spreading your money across different investments so one bad pick doesn''t sink you. Don''t put it all in one stock.', 'workbook pre-course A5; textbook p143'),
  ('w1-teens-009', 1, 'teens', 'Bull market vs. bear market', 'Bull market: prices rising. Bear market: prices falling. Easy way to remember: bulls charge up, bears swipe down.', 'textbook p7'),
  ('w1-teens-010', 1, 'teens', 'Risk tolerance', 'How much of a drop in your money you can handle without panicking. Higher returns usually mean you have to stomach bigger swings.', 'textbook p7'),
  ('w1-teens-011', 1, 'teens', 'What is the stock market?', 'A network of exchanges where people buy and sell shares of companies. It''s not one building; it''s a giant matching system for buyers and sellers.', 'workbook pre-course A2; textbook p11'),
  ('w1-teens-012', 1, 'teens', 'What moves a stock''s price?', 'Supply and demand. More buyers than sellers pushes the price up; more sellers than buyers pushes it down. That''s it.', 'workbook ch2; textbook p11'),
  ('w1-teens-013', 1, 'teens', 'Ticker symbol', 'A short code that names a stock, like AAPL for Apple or NKE for Nike. Traders use it so there''s no mix-up.', 'workbook pre-course A3; textbook p12'),
  ('w1-teens-014', 1, 'teens', 'What is a market index?', 'A scoreboard for a chunk of the market. Instead of tracking one stock, it tracks a group so you can see how the market is doing overall.', 'textbook p13'),
  ('w1-teens-015', 1, 'teens', 'The three big indices', 'The Dow (30 large companies), the S&P 500 (500 big U.S. companies), and the NASDAQ Composite (tech-heavy). People quote these to describe ''the market.''', 'workbook ch2; textbook p14'),
  ('w1-teens-016', 1, 'teens', 'Uptrend vs. downtrend', 'Uptrend = higher highs and higher lows (stairs going up). Downtrend = lower highs and lower lows (stairs going down). And no trend lasts forever.', 'workbook ch2; textbook p15'),
  ('w1-teens-017', 1, 'teens', 'IPO', 'When a private company sells stock to the public for the first time to raise money. After the IPO, anyone can trade its shares.', 'textbook p11'),
  ('w1-teens-018', 1, 'teens', '''The trend is your friend''', 'It''s usually smarter to trade with the current trend than to fight it. Go with the flow until the trend clearly changes.', 'workbook ch2'),
  ('w2-teens-001', 2, 'teens', 'What is technical analysis?', 'Reading price charts to spot patterns, based on the idea that market behavior tends to repeat. It''s about what price is doing, not the company''s report card.', 'workbook ch3; textbook p93'),
  ('w2-teens-002', 2, 'teens', 'What is a candlestick?', 'One candle sums up a day (or any time period): where price opened, closed, and how high and low it went. It''s a mini story of the fight between buyers and sellers.', 'workbook ch3; textbook p94'),
  ('w2-teens-003', 2, 'teens', 'Green candle vs. red candle', 'Green: price closed higher than it opened, so buyers won that period. Red: price closed lower than it opened, so sellers won.', 'workbook pre-course B6; textbook p94'),
  ('w2-teens-004', 2, 'teens', 'The body and the wicks', 'The body is the open-to-close range. The wicks (thin lines) show the highest and lowest prices reached. Long wicks mean price got rejected up there or down there.', 'workbook ch3; textbook p94'),
  ('w2-teens-005', 2, 'teens', 'Long body vs. short body', 'A long body = strong, one-sided pressure that period. A short body = a close fight and low volatility, nobody really won.', 'textbook p94'),
  ('w2-teens-006', 2, 'teens', 'Support', 'A price floor where a stock tends to stop falling and bounce back up. Buyers keep showing up around that level.', 'workbook pre-course B7; textbook p98'),
  ('w2-teens-007', 2, 'teens', 'Resistance', 'A price ceiling where a stock tends to stop rising and fall back down. Sellers keep showing up around that level.', 'workbook ch3; textbook p98'),
  ('w2-teens-008', 2, 'teens', 'Trendline', 'A line you draw connecting the higher lows in an uptrend (or lower highs in a downtrend). It shows the trend''s direction and where price might bounce.', 'workbook ch3; textbook p101'),
  ('w2-teens-009', 2, 'teens', 'Volume', 'How many shares traded. Big volume behind a move means it''s serious; a move on tiny volume is weak and easy to distrust.', 'workbook ch4; textbook p117'),
  ('w2-teens-010', 2, 'teens', 'Timeframe', 'The time each candle covers, from 1 minute to 1 week. Zoom out for the big picture, zoom in for the details, and check that they agree.', 'workbook ch3; textbook p100'),
  ('w2-teens-011', 2, 'teens', 'Line chart vs. candlestick chart', 'A line chart just connects closing prices. A candlestick shows open, high, low, and close, so it tells you way more about each period.', 'textbook p95'),
  ('w2-teens-012', 2, 'teens', 'Sideways (consolidation)', 'When price bounces between support and resistance with no clear direction. It''s often a pause before a breakout.', 'textbook p18, p99'),
  ('w2-teens-013', 2, 'teens', 'Breakout', 'When price pushes through support or resistance and keeps going. A breakout on strong volume is more believable than one on weak volume.', 'workbook ch3; textbook p103'),
  ('w2-teens-014', 2, 'teens', 'Why does a candle chart matter?', 'It shows the tug-of-war between buyers and sellers in real time, which helps you guess who''s likely to win next.', 'textbook p94-95'),
  ('w2-teens-015', 2, 'teens', 'Higher highs, higher lows', 'The signature of an uptrend: each peak tops the last and each dip is shallower than the last. Flip it for a downtrend.', 'workbook ch2; textbook p15'),
  ('w2-teens-016', 2, 'teens', 'Support can flip to resistance', 'Once price breaks below an old support level, that level often becomes new resistance on the way back up (and vice versa).', 'textbook p99'),
  ('w3-teens-001', 3, 'teens', 'Chart pattern', 'A repeating shape price makes on a chart that hints what might come next. Some say the trend continues; others warn it''s about to reverse.', 'workbook ch5; textbook p105'),
  ('w3-teens-002', 3, 'teens', 'Head and shoulders', 'Three peaks with a tall one in the middle. It usually warns a trend is about to flip (often to the downside) once price breaks the neckline.', 'workbook pre-course B10; textbook p107'),
  ('w3-teens-003', 3, 'teens', 'Double top / double bottom', 'Price hits a level twice and gets rejected. Double top = watch for a drop. Double bottom = watch for a rise.', 'workbook ch5; textbook p138'),
  ('w3-teens-004', 3, 'teens', 'Moving average', 'A line showing the average closing price over a set number of days, like the 50-day. It smooths out the noise so you can see the real trend.', 'workbook pre-course B8; textbook p117'),
  ('w3-teens-005', 3, 'teens', 'SMA vs. EMA', 'The Simple MA treats every day equally. The Exponential MA cares more about recent days, so it reacts faster to new price action.', 'workbook ch4; textbook p118'),
  ('w3-teens-006', 3, 'teens', 'Golden cross vs. death cross', 'Golden cross: a short MA crosses above a long MA (bullish sign). Death cross: short MA drops below long MA (bearish sign).', 'workbook ch4; textbook p118'),
  ('w3-teens-007', 3, 'teens', 'RSI', 'Relative Strength Index, a 0-100 meter. Over 70 = possibly overbought (ran too hot). Under 30 = possibly oversold (dropped too far).', 'workbook pre-course B9; textbook p116'),
  ('w3-teens-008', 3, 'teens', 'MACD', 'A momentum indicator built from two moving averages. It flags when momentum is shifting, hinting at a possible trend change or continuation.', 'workbook ch5; textbook p115'),
  ('w3-teens-009', 3, 'teens', 'Bollinger Bands', 'A moving average with a band above and below it. Bands squeezing together = calm/low volatility; bands spreading wide = big moves happening.', 'workbook ch5; textbook p116'),
  ('w3-teens-010', 3, 'teens', 'What is fundamental analysis?', 'Judging a company by its actual business: sales, profit, and financial health, to figure out what it''s really worth. Technical analysis reads the chart; fundamental analysis reads the company.', 'workbook ch2; textbook p73'),
  ('w3-teens-011', 3, 'teens', 'P/E ratio', 'Price divided by earnings per share. A high P/E means investors are paying a lot for each dollar the company earns, usually betting on future growth.', 'workbook pre-course A4; textbook p89'),
  ('w3-teens-012', 3, 'teens', 'EPS', 'Earnings per share: how much profit the company made for each share of stock. Higher EPS generally means a more profitable company.', 'textbook p69'),
  ('w3-teens-013', 3, 'teens', 'The three financial statements', 'Income statement (did it make money?), balance sheet (what it owns vs. owes), and cash flow statement (where cash actually went).', 'workbook ch2; textbook p76'),
  ('w3-teens-014', 3, 'teens', 'What is a catalyst?', 'News or an event, like an earnings report or a new product, that can move a stock fast. Traders watch the calendar for these.', 'textbook p73, p186'),
  ('w3-teens-015', 3, 'teens', 'Growth vs. value stock', 'Growth stock: expected to grow fast, you profit if the price climbs. Value stock: looks cheap for what the company is worth, you bet the market catches on.', 'workbook ch3; textbook p23'),
  ('w3-teens-016', 3, 'teens', 'Why confirm a breakout with volume?', 'Volume is the proof. A breakout backed by a surge in volume means lots of traders agree; on weak volume it often fails.', 'workbook ch3; textbook p138'),
  ('w4-teens-001', 4, 'teens', 'What is an option?', 'A contract giving you the right, but not the obligation, to buy or sell a stock at a set price before a deadline. Two kinds: calls and puts.', 'workbook ch6; textbook p141'),
  ('w4-teens-002', 4, 'teens', 'Call option', 'The right to BUY a stock at a set price. You buy calls when you think the price is going UP.', 'workbook pre-course C11; textbook p141'),
  ('w4-teens-003', 4, 'teens', 'Put option', 'The right to SELL a stock at a set price. You buy puts when you think the price is going DOWN.', 'workbook pre-course C12; textbook p141'),
  ('w4-teens-004', 4, 'teens', 'Strike price', 'The set price in the contract where you can buy (call) or sell (put) the stock, no matter what the market price is.', 'workbook ch6; textbook p142'),
  ('w4-teens-005', 4, 'teens', 'Premium', 'The price you pay to buy an option contract. If you''re buying options, the premium is the most you can lose.', 'workbook ch6; textbook p142'),
  ('w4-teens-006', 4, 'teens', 'Expiration date', 'The deadline. After this date the option is done and worthless if it never got in-the-money.', 'workbook ch6; textbook p142'),
  ('w4-teens-007', 4, 'teens', 'In-the-money vs. out-of-the-money', 'In-the-money means the option has real value right now (a call below the current price, a put above it). Out-of-the-money means it has no built-in value yet.', 'textbook p142'),
  ('w4-teens-008', 4, 'teens', 'Leverage', 'Options let you control a big position with a small amount of money. That can multiply gains, but it can also multiply losses, so respect it.', 'workbook ch6; textbook p142'),
  ('w4-teens-009', 4, 'teens', 'Why are options risky?', 'They expire. If the stock doesn''t move your way before the deadline, the option can go to zero and you lose the whole premium.', 'workbook ch6; textbook p143'),
  ('w4-teens-010', 4, 'teens', 'Protective put = insurance', 'Buying a put on a stock you own is like insurance: if the stock crashes, the put gains value and cushions your loss.', 'workbook ch6; textbook p207'),
  ('w4-teens-011', 4, 'teens', 'Covered call', 'Selling a call on stock you already own to collect extra income. Works best when you expect the stock to move sideways.', 'textbook p161'),
  ('w4-teens-012', 4, 'teens', 'Time decay (why deadlines hurt)', 'An option loses value as its expiration date gets closer, because there''s less time left for the stock to move. Waiting costs you.', 'workbook ch6; textbook p142'),
  ('w4-teens-013', 4, 'teens', 'Bullish vs. bearish play', 'Bullish (expect up)? Buy a call. Bearish (expect down)? Buy a put. Your outlook picks the tool.', 'textbook p144'),
  ('w4-teens-014', 4, 'teens', 'Pick companies you actually know', 'It''s easier to have an informed view on companies your family uses, like Apple, Nike, or Disney, than on names you''ve never heard of.', 'workbook ch1, ch3'),
  ('w4-teens-015', 4, 'teens', 'Should beginners jump into options?', 'No. Options add risk and complexity. Learn stocks first, practice on paper, and understand each contract before using real money.', 'workbook ch6; textbook p145'),
  ('w5-teens-001', 5, 'teens', 'What is risk management?', 'Protecting your money first. It''s the habits that keep one bad trade from wiping you out. It reduces risk; it can''t erase it.', 'workbook ch7; textbook p163'),
  ('w5-teens-002', 5, 'teens', 'Position sizing', 'Deciding how much to put into one trade. Rule of thumb: keep any single position small enough that a loss won''t hurt the whole account.', 'workbook ch7; textbook p169'),
  ('w5-teens-003', 5, 'teens', 'Percent-of-portfolio sizing', 'Risking a set slice of your account per trade, for example 2% into a risky pick and more into a safe one. Keeps any one bet in check.', 'workbook ch7; textbook p169'),
  ('w5-teens-004', 5, 'teens', 'Stop-loss order', 'An automatic sell that triggers if the price drops to a level you set. It''s your safety net, like a parachute you set and forget.', 'workbook pre-course C13; textbook p164'),
  ('w5-teens-005', 5, 'teens', 'How to calculate a stop-loss', 'Take your buy price and subtract your max loss percent. Buy at $250 with a 10% stop? Your stop is $225.', 'workbook ch7 activity; textbook p164'),
  ('w5-teens-006', 5, 'teens', 'Risk-return tradeoff', 'Bigger potential reward almost always means bigger risk. If someone promises high returns with zero risk, it''s a red flag.', 'workbook pre-course C14; textbook p164'),
  ('w5-teens-007', 5, 'teens', 'Diversification', 'Spread money across different companies, sectors, and asset types. If one drops, the others cushion the fall.', 'workbook ch7; textbook p167'),
  ('w5-teens-008', 5, 'teens', 'Plans over feelings', 'Fear and greed make traders sell low and buy high. A written plan with entry, exit, and stop keeps emotions from running your money.', 'workbook ch7; textbook p165'),
  ('w5-teens-009', 5, 'teens', 'Small losses are wins', 'Cutting a loser quickly is a win, because it protects your capital for the next good trade. Big losses are what end accounts.', 'workbook ch7; textbook p164'),
  ('w5-teens-010', 5, 'teens', 'Know your risk tolerance', 'Factor in your goals, time horizon, and how you handle a drop. If big swings make you panic-sell, size smaller and play safer.', 'workbook ch7; textbook p165'),
  ('w5-teens-011', 5, 'teens', 'Inflation is a risk too', 'If your money earns 1% but prices rise 4%, you''re actually losing buying power. Cash sitting still loses value over time.', 'workbook ch7 activity'),
  ('w5-teens-012', 5, 'teens', 'Rebalancing', 'Over time winners grow bigger than planned and throw off your mix. Rebalancing means trimming and adding to get back to your target.', 'workbook ch7; textbook p167'),
  ('w5-teens-013', 5, 'teens', 'Journaling your trades', 'Write down why you entered, your plan, and what happened. Reviewing your journal is how you spot mistakes and actually improve.', 'workbook ch7; textbook p166'),
  ('w5-teens-014', 5, 'teens', 'Don''t chase ''guaranteed'' returns', 'No real investment guarantees profits. Hype promising sure wins usually hides risk you can''t see yet.', 'workbook ch7; textbook p164'),
  ('w5-teens-015', 5, 'teens', 'Why diversification can''t fix everything', 'It protects against one company failing, but not against the whole market falling at once. It lowers risk; it doesn''t remove it.', 'workbook ch7 activity; textbook p167'),
  ('w6-teens-001', 6, 'teens', 'What is a brokerage account?', 'An account that lets you buy and sell investments. Think of it as an online store account, but for stocks instead of sneakers.', 'workbook ch8; textbook p174'),
  ('w6-teens-002', 6, 'teens', 'The Investment Store analogy', 'A brokerage is the middleman connecting you (the buyer) with people selling stocks. Just like you need an Amazon account to shop online, you need a brokerage to invest.', 'workbook ch8 analogy'),
  ('w6-teens-003', 6, 'teens', 'Custodial account (your option under 18)', 'A UTMA/UGMA account a parent opens in your name and manages until you''re 18 (or 21 in some states). The money is legally yours; it lets you start early.', 'workbook ch8'),
  ('w6-teens-004', 6, 'teens', 'Market order', 'Buy or sell right now at whatever the current price is. Fast, but the exact price can shift a bit, especially on wild days.', 'textbook p181'),
  ('w6-teens-005', 6, 'teens', 'Limit order', 'Buy or sell only at your price or better. You control the price, but the trade only happens if the market reaches it.', 'textbook p181'),
  ('w6-teens-006', 6, 'teens', 'Stop order', 'A trigger order: once price hits your stop level, it turns into a market order. Often used to cap a loss automatically.', 'textbook p182'),
  ('w6-teens-007', 6, 'teens', 'Steps to place a trade', 'Log in, search the stock, pick buy or sell, set order type and quantity, review the details, confirm, then watch the order fill.', 'workbook ch8; textbook p181'),
  ('w6-teens-008', 6, 'teens', 'Commission-free trading', 'Most brokerages now charge $0 to trade stocks. That means small investors can buy a few shares without fees eating the gains.', 'workbook ch8; textbook p174'),
  ('w6-teens-009', 6, 'teens', 'Paper trading', 'Practicing trades with fake money in a real-feeling app. It''s how you build skills and make mistakes for free before risking real cash.', 'workbook ch8; textbook p171'),
  ('w6-teens-010', 6, 'teens', 'First-trade checklist', 'Know why you''re buying, decide your entry, your exit, and your stop, size the position small, then place the order and log it.', 'workbook ch7-8; textbook p181'),
  ('w6-teens-011', 6, 'teens', 'Bid vs. ask', 'The bid is the highest price a buyer will pay; the ask is the lowest a seller will take. The small gap between them is the spread.', 'textbook p183'),
  ('w6-teens-012', 6, 'teens', 'Roth IRA (why teens love it)', 'A retirement account funded with money you already paid tax on, so it grows tax-free and comes out tax-free later. Decades of tax-free compounding.', 'workbook ch8; textbook p191'),
  ('w6-teens-013', 6, 'teens', 'How do you pick a broker?', 'Compare fees, how easy the app is, what you can invest in, and support. Try the demo or paper-trading mode before committing.', 'workbook ch8; textbook p175'),
  ('w6-teens-014', 6, 'teens', 'Reading a stock dashboard', 'It shows current price, volume, P/E, market cap, 52-week high/low, and news, everything you need to size up a stock at a glance.', 'textbook p183-184'),
  ('w6-teens-015', 6, 'teens', 'Make a family trade plan', 'Before your first real trade, agree with a parent on which company, how much, your exit, and your stop. Shared rules keep it disciplined.', 'workbook ch8; textbook p181'),
  ('w1-kids-001', 1, 'kids', 'What is investing?', 'Investing means planting your money early so it can grow. Saving keeps money safe and the same. Investing puts it to work.', 'workbook ch1; orientation deck (INVESTING = plant money early)'),
  ('w1-kids-002', 1, 'kids', 'What is a stock?', 'A stock is a small piece of a company. Own one and you own a tiny part of that company, like owning a slice of a pizza.', 'Learn 2 Earn; PTG Quick Reference; lesson plans Unit 1 (pizza ownership)'),
  ('w1-kids-003', 1, 'kids', 'The four ways to make money', 'Work (trade your time), Business (build something that earns), Investing (plant money and let it grow), and Trading (use your skill to grow money). Wealthy families do all four.', 'orientation deck ACT 1 (4 ways)'),
  ('w1-kids-004', 1, 'kids', 'How does a stock make you money?', 'You try to buy a piece of a good company at a good price. If the company does well, your piece can be worth more later.', 'Learn 2 Earn'),
  ('w1-kids-005', 1, 'kids', 'What is inflation?', 'Inflation means prices slowly go up over time. A snack that costs $1 today might cost more later, so money sitting still buys less.', 'Learn 2 Earn (inflation)'),
  ('w1-kids-006', 1, 'kids', 'Why start investing young?', 'Money needs time to grow. A dollar planted at age 10 beats a dollar planted at age 40, every time. Time is your superpower.', 'workbook ch1; orientation deck (dollar planted at 10 beats 40)'),
  ('w1-kids-007', 1, 'kids', 'What is profit?', 'Profit is the money a company keeps after it pays all its costs. Companies with good profit can be good to own.', 'Learn 2 Earn (Revenue, Expenses & Profits)'),
  ('w1-kids-008', 1, 'kids', 'What is a dividend?', 'A dividend is a little cash payment some companies give the people who own their stock. It is like getting paid just to own it.', 'PTG Quick Reference; textbook p6'),
  ('w1-kids-009', 1, 'kids', 'What is an ETF?', 'An ETF is a basket of many stocks you buy all at once. One purchase gives you a little of lots of companies, so you are not betting on just one.', 'PTG Quick Reference'),
  ('w1-kids-010', 1, 'kids', 'What is a bond?', 'A bond is a loan you give to a company or the government. They pay you back later with a little extra. Owning a stock is owning; a bond is lending.', 'textbook p6'),
  ('w1-kids-011', 1, 'kids', 'What is trading?', 'Trading is using your SKILL to grow money by buying and selling the moves in the market, over days and weeks. It can make money when prices go up AND when they go down.', 'orientation deck ACT 1 (TRADING = skill makes money grow)'),
  ('w1-kids-012', 1, 'kids', 'Bull market vs. bear market', 'Bull market: prices are going up (bulls thrust UP). Bear market: prices are going down (bears swipe DOWN).', 'PTG Quick Reference; textbook p7'),
  ('w1-kids-013', 1, 'kids', 'What is compound interest?', 'You earn money on your money, and then earn even more on THAT. It snowballs. That is why starting early is so powerful.', 'PTG Quick Reference; textbook p5'),
  ('w1-kids-014', 1, 'kids', 'Companies you already know', 'You can learn about companies you use every day, like Apple, Nike, Disney, or Roblox. You already know if you like their stuff!', 'workbook ch1; orientation deck homework (pick 5 companies your family uses)'),
  ('w1-kids-015', 1, 'kids', 'The cheat code: trading funds the rest', 'Trading is a skill you can learn young. When you get good, it can help pay for investing and even a business one day. It feeds the other ways to make money.', 'orientation deck ACT 4 (trading funds all of them)'),
  ('w2-kids-001', 2, 'kids', 'What is the stock market?', 'A giant place where people buy and sell tiny pieces of companies. It is not one building, it is lots of computers connected together.', 'workbook ch2; textbook p11'),
  ('w2-kids-002', 2, 'kids', 'The market is like a store', 'The stock market is like a huge store, but instead of toys or food you buy and sell pieces of companies.', 'workbook ch2; textbook p11'),
  ('w2-kids-003', 2, 'kids', 'Every price is a tug-of-war', 'The price is a rope, with buyers pulling one way and sellers pulling the other. Whichever side is stronger, that is the way the price moves.', 'orientation deck Lesson Zero LZ-3 (tug-of-war)'),
  ('w2-kids-004', 2, 'kids', 'What makes a price go UP?', 'When more people want to BUY than sell, the buyers pull harder on the rope and the price climbs.', 'orientation deck LZ-4; Learn 2 Earn (buyers vs sellers)'),
  ('w2-kids-005', 2, 'kids', 'What makes a price go DOWN?', 'When more people want to SELL than buy, the sellers pull harder on the rope and the price falls.', 'orientation deck LZ-4; Learn 2 Earn (buyers vs sellers)'),
  ('w2-kids-006', 2, 'kids', 'What is a ticker symbol?', 'A ticker is a short nickname for a stock. Apple is AAPL and Nike is NKE. It helps everyone know exactly which stock you mean.', 'workbook ch2; textbook p12'),
  ('w2-kids-007', 2, 'kids', 'One candle = one battle', 'Each candle is one round of the tug-of-war. It shows where the price started, where it ended, and how high and low the fight went that day.', 'orientation deck LZ-5 (one candle = one battle); textbook p94'),
  ('w2-kids-008', 2, 'kids', 'Green candle = green team won', 'A green candle means the price ended HIGHER than it started. The buyers (green team) won that battle.', 'orientation deck LZ-5; workbook candle activity'),
  ('w2-kids-009', 2, 'kids', 'Red candle = red team won', 'A red candle means the price ended LOWER than it started. The sellers (red team) won that battle.', 'orientation deck LZ-5; workbook candle activity'),
  ('w2-kids-010', 2, 'kids', 'The wick = how far the fight swung', 'The thin line sticking out of a candle is the wick. It shows how far the price swung up or down during the battle before it settled.', 'orientation deck LZ-5 (wick = how far the fight swung); textbook p94'),
  ('w2-kids-011', 2, 'kids', 'A chart is battles in a row', 'A whole chart is just lots of candle-battles lined up. Look at them together to see who has been winning the war: the buyers or the sellers.', 'orientation deck LZ-6 (a chart is just battles in a row)'),
  ('w2-kids-012', 2, 'kids', 'What is support?', 'Support is like an invisible FLOOR on the chart. The price often stops falling and bounces back up when it reaches the floor.', 'workbook ch5 (floors and ceilings); textbook p98'),
  ('w2-kids-013', 2, 'kids', 'What is resistance?', 'Resistance is like an invisible CEILING on the chart. The price often stops rising and comes back down when it reaches the ceiling.', 'workbook ch5 (floors and ceilings); textbook p98'),
  ('w2-kids-014', 2, 'kids', 'What is a trend?', 'A trend is the way the price is mostly heading: up, down, or sideways. It is the answer to who has been winning the war.', 'workbook ch2; orientation deck LZ-6'),
  ('w2-kids-015', 2, 'kids', 'Reading trend is your first pro skill', 'Looking at a chart and saying ''climbing or falling?'' is called reading the trend. It is the very first thing every pro checks.', 'orientation deck LZ-8 (you just read TREND)'),
  ('w2-kids-016', 2, 'kids', 'What is a timeframe?', 'A timeframe is how much time each candle covers, like one day or one week. Zoom out to see the big war, zoom in to see one battle.', 'textbook p100'),
  ('w3-kids-001', 3, 'kids', 'How do you read a candle?', 'Ask one question: did the green team (buyers) or the red team (sellers) win that battle? Green up means buyers, red down means sellers.', 'orientation deck LZ-5; workbook candle activity'),
  ('w3-kids-002', 3, 'kids', 'What does a TALL candle mean?', 'A tall candle means one side won by a LOT. A tall green candle means the buyers were super strong that battle.', 'workbook candle activity; textbook p94'),
  ('w3-kids-003', 3, 'kids', 'What do long wicks tell you?', 'Long wicks mean the fight swung far before settling. It shows the battle was wild and both sides fought hard.', 'orientation deck LZ-5; textbook p94'),
  ('w3-kids-004', 3, 'kids', 'Three green candles in a row', 'Three tall green candles in a row means the buyers keep winning, so the price keeps climbing. That is an uptrend.', 'workbook candle activity; orientation deck LZ-6'),
  ('w3-kids-005', 3, 'kids', 'What is an uptrend?', 'An uptrend is when the price keeps making higher highs and higher lows, like climbing stairs going up. The buyers are winning the war.', 'workbook ch2; textbook p15'),
  ('w3-kids-006', 3, 'kids', 'What is a downtrend?', 'A downtrend is when the price keeps making lower highs and lower lows, like walking down stairs. The sellers are winning the war.', 'workbook ch2; textbook p15'),
  ('w3-kids-007', 3, 'kids', 'What is a moving average?', 'A moving average is a smooth line that shows the average price over the last few days. It helps you see the trend without all the bumps.', 'workbook ch4; textbook p117'),
  ('w3-kids-008', 3, 'kids', 'What is volume?', 'Volume is how many shares traded, like the size of the crowd. A big crowd behind a move means it is more serious.', 'workbook ch4; textbook p117'),
  ('w3-kids-009', 3, 'kids', 'How do you spot a trend?', 'Look at the whole chart of battles. Are the candles mostly climbing, mostly falling, or moving flat? That is the trend.', 'workbook ch3; orientation deck LZ-7'),
  ('w3-kids-010', 3, 'kids', 'Does a trend last forever?', 'No. No trend lasts forever. A price going up can start going down, so keep watching the battles.', 'workbook ch2; textbook p18'),
  ('w3-kids-011', 3, 'kids', 'What is a chart pattern?', 'A chart pattern is a shape the price makes that shows up again and again. Learning the shapes gives you clues about what might happen next.', 'workbook ch5; textbook p105'),
  ('w3-kids-012', 3, 'kids', 'The head and shoulders shape', 'It looks like three bumps: a tall one in the middle with a shoulder on each side. It usually warns that an uptrend is about to flip and fall.', 'workbook ch5; textbook p107'),
  ('w3-kids-013', 3, 'kids', 'Double top and double bottom', 'When the price bumps a level twice and gets pushed back both times. A double top can mean a drop is coming; a double bottom can mean a rise.', 'workbook ch5; textbook p138'),
  ('w3-kids-014', 3, 'kids', 'What is RSI?', 'RSI is like a hot-or-cold meter from 0 to 100. Over 70 means the stock ran too hot (overbought). Under 30 means it got too cold (oversold).', 'workbook Pre-Course B9; textbook p116'),
  ('w3-kids-015', 3, 'kids', 'What is a P/E ratio?', 'Price divided by earnings. It shows how much you pay for each $1 a company earns. It helps you compare if a stock is cheap or pricey.', 'PTG Quick Reference; textbook p89'),
  ('w3-kids-016', 3, 'kids', 'Reading the chart vs. reading the company', 'Technical analysis studies the chart and the battles. Fundamental analysis studies the company itself: does it make money and sell things people love?', 'workbook ch2-3; textbook p73, p93'),
  ('w3-kids-017', 3, 'kids', 'What is a catalyst?', 'A catalyst is big news, like a great new product or earnings report, that can send lots of people to one side of the rope and move a stock fast.', 'textbook p73; orientation deck LZ-3 (news sends people to one side)'),
  ('w4-kids-001', 4, 'kids', 'Pick companies your family uses', 'The best companies to learn about are ones your family already uses, like your shoes, phone, or favorite game. You already know if they are good.', 'workbook ch1, ch3; orientation deck homework'),
  ('w4-kids-002', 4, 'kids', 'What makes a company strong?', 'A strong company makes more money than it spends, sells things people love, and keeps growing. That is a company worth watching.', 'Learn 2 Earn (Revenue, Expenses & Profits)'),
  ('w4-kids-003', 4, 'kids', 'What is revenue?', 'Revenue is all the money a company brings in from selling its stuff, before it pays any costs. Money coming in.', 'Learn 2 Earn (Revenue)'),
  ('w4-kids-004', 4, 'kids', 'What are expenses?', 'Expenses are the costs a company pays to run, like paying workers and buying supplies. Money going out.', 'Learn 2 Earn (Expenses)'),
  ('w4-kids-005', 4, 'kids', 'The winning move', 'The goal is to buy the BEST company, at the BEST price, at the RIGHT time. All three together is the winning move.', 'Learn 2 Earn (''Our Job Is to...'')'),
  ('w4-kids-006', 4, 'kids', 'What is a call (simple)?', 'A call is a bet that a price will go UP. If you think a company will do great, that is an ''up'' idea, also called bullish.', 'workbook ch6; textbook p141'),
  ('w4-kids-007', 4, 'kids', 'What is a put (simple)?', 'A put is a bet that a price will go DOWN. If you think a company will struggle, that is a ''down'' idea, also called bearish.', 'workbook ch6; textbook p141'),
  ('w4-kids-008', 4, 'kids', 'Do your homework first', 'Before you pick a company, learn about it. Does it make money? Do people like it? Smart pickers look before they leap.', 'workbook ch2; textbook p73'),
  ('w4-kids-009', 4, 'kids', 'Don''t put everything in one company', 'Never put all your money in one company. If you own a few different ones, a bad day for one is not a disaster.', 'workbook ch7; PTG Quick Reference (don''t put all eggs in one basket)'),
  ('w4-kids-010', 4, 'kids', 'What is an option?', 'An option is the RIGHT, but not the must, to buy or sell at a set price. It is an advanced tool, so beginners learn it but wait before using it.', 'PTG Quick Reference (Option: advanced, avoid for now); textbook p141'),
  ('w4-kids-011', 4, 'kids', 'What is the strike price?', 'The strike price is the set price in the option deal, the price you could buy or sell at, no matter where the real price goes.', 'workbook ch6; textbook p142'),
  ('w4-kids-012', 4, 'kids', 'What is the premium?', 'The premium is the price you pay to buy an option, like the cost of the ticket. If you buy options, that ticket price is the most you can lose.', 'workbook ch6; textbook p142-143'),
  ('w4-kids-013', 4, 'kids', 'Options have a deadline', 'Every option has an expiration date. After that day it is over. If the price never moved your way in time, the option becomes worthless.', 'workbook ch6; textbook p142'),
  ('w4-kids-014', 4, 'kids', 'Why waiting costs you (time decay)', 'An option slowly loses value as its deadline gets closer, because there is less time left for the price to move. Waiting quietly costs you.', 'textbook p142 (time value)'),
  ('w4-kids-015', 4, 'kids', 'Why beginners skip options at first', 'Options are complex, with strike prices, dates, and premiums, and they can expire worthless. Learn stocks first and practice before trying them.', 'PTG Chapter 6/8 (why to avoid options for now); textbook p145'),
  ('w4-kids-016', 4, 'kids', 'What can you actually trade?', 'You can trade stocks and options first. Later you can learn others like forex, commodities, crypto, and futures. Stocks are the best place to start.', 'orientation deck (6-asset grid; stocks + options beta focus)'),
  ('w5-kids-001', 5, 'kids', 'House Rule 1: Protect the money first', 'The number one job of a smart trader is to protect the money. Keeping what you have comes before trying to win big.', 'orientation deck FTA House Rules #1; textbook p163'),
  ('w5-kids-002', 5, 'kids', 'House Rule 2: Plans over feelings', 'Do not trade because you feel excited or scared. Make a plan first and follow it. The gambler hopes; the trader plans.', 'orientation deck FTA House Rules #2; textbook p165'),
  ('w5-kids-003', 5, 'kids', 'House Rule 3: Practice before we play', 'Practice with pretend money until you are good, then use real money. Every pro practices first.', 'orientation deck FTA House Rules #3; textbook p171'),
  ('w5-kids-004', 5, 'kids', 'House Rule 4: Small losses are wins', 'Every trader has losing trades. A small loss is a WIN because you kept most of your money for the next chance.', 'orientation deck FTA House Rules #4; textbook p164'),
  ('w5-kids-005', 5, 'kids', 'House Rule 5: We learn out loud', 'Ask questions, share what you find, and talk about your trades. The ''dumb'' question is never just yours. We learn out loud, together.', 'orientation deck FTA House Rules #5'),
  ('w5-kids-006', 5, 'kids', 'What is a stop-loss?', 'A stop-loss is a safety net. You pick a price, and if the stock drops to it, it sells for you automatically so you do not lose too much.', 'workbook ch7; textbook p164'),
  ('w5-kids-007', 5, 'kids', 'Don''t put it all in one place', 'Spread your money across a few different companies. That way one bad pick can''t take it all. This is called diversifying.', 'workbook ch7; PTG Quick Reference (don''t put all eggs in one basket)'),
  ('w5-kids-008', 5, 'kids', 'Only risk a little on each trade', 'Smart traders only put a small part of their money in any one trade, so no single mistake can hurt them badly. This is called position sizing.', 'workbook ch7; textbook p169'),
  ('w5-kids-009', 5, 'kids', 'Bigger reward, bigger risk', 'The chance for a big reward usually comes with a bigger chance of losing. If something sounds like a sure, safe, huge win, be careful.', 'workbook ch7; textbook p164'),
  ('w5-kids-010', 5, 'kids', 'The gambler hopes, the trader plans', 'Gambling is guessing and hoping. Trading is a skill with a plan and rules. A trader knows the plan before they start.', 'orientation deck (Trading IS/ISN''T)'),
  ('w5-kids-011', 5, 'kids', 'Keep a trading notebook', 'Write down what you bought and why. Later you can look back and learn from your wins and your mistakes.', 'workbook ch7; textbook p166'),
  ('w5-kids-012', 5, 'kids', 'Stay calm when prices drop', 'Prices go up and down. That is normal. Do not panic and sell everything. Take a breath and check your plan.', 'workbook ch7; textbook p165'),
  ('w5-kids-013', 5, 'kids', 'The bait and the grab', 'Sometimes a price dips just a little to trick people into selling, then rockets up. Pros ask, ''where are everyone''s stop-losses hiding?'' You will learn to spot this later.', 'orientation deck LZ-9 (the bait & the grab; pool-party liquidity)'),
  ('w5-kids-014', 5, 'kids', 'Inflation is a risk too', 'If your money just sits there while prices go up, it slowly buys less. Money standing still is quietly losing.', 'workbook ch7; orientation deck (money sitting still loses)'),
  ('w5-kids-015', 5, 'kids', 'Why diversifying can''t fix everything', 'Spreading out protects you if one company fails. But if the whole market drops at once, everything can dip. It lowers risk; it can''t erase it.', 'workbook ch7; textbook p167'),
  ('w6-kids-001', 6, 'kids', 'What is a brokerage?', 'A brokerage is like an Investment Store. It is the helper that lets you buy and sell stocks, like an app that lets you shop online.', 'workbook ch8 (Investment Store analogy)'),
  ('w6-kids-002', 6, 'kids', 'Can a kid invest?', 'Yes! A parent can open a special custodial account in your name and help you until you grow up. The money is legally yours.', 'workbook ch8; PTG Chapter 8 (custodial accounts)'),
  ('w6-kids-003', 6, 'kids', 'What is paper trading?', 'Paper trading is practicing with pretend money. You make real choices but risk nothing, so it is the perfect way to learn.', 'workbook ch8; textbook p171'),
  ('w6-kids-004', 6, 'kids', 'Your first pretend trade', 'Pick a company you like, choose how much pretend money to use, and ''buy'' it. Then watch what happens and learn from it.', 'workbook ch8; textbook p181'),
  ('w6-kids-005', 6, 'kids', 'Make a family trade plan', 'Before trading, make a plan with a grown-up: which company, how much, and when to sell. Planning together keeps it smart and safe.', 'workbook ch8; textbook p181'),
  ('w6-kids-006', 6, 'kids', 'What is an order?', 'An order is you telling the Investment Store you want to buy or sell. Then it makes the trade happen for you.', 'workbook ch8; textbook p181'),
  ('w6-kids-007', 6, 'kids', 'Market order vs. limit order', 'A market order buys or sells right now at the current price. A limit order only trades at the price you choose or better. Now versus your price.', 'textbook p181'),
  ('w6-kids-008', 6, 'kids', 'What is a stop order?', 'A stop order is a trigger. When the price hits the level you set, it turns into a real order. It is often used with a stop-loss to protect your money.', 'textbook p182'),
  ('w6-kids-009', 6, 'kids', 'What is a Roth IRA?', 'A Roth IRA is a special account where your money grows TAX-FREE. Started young with earned money, it could grow into a huge amount over your life.', 'PTG Quick Reference; PTG Chapter 8 (power of the Roth IRA)'),
  ('w6-kids-010', 6, 'kids', 'What are fractional shares?', 'You do not need lots of money. Fractional shares let you buy a tiny slice of an expensive stock like Amazon or Google with just a few dollars.', 'PTG Chapter 8 (fractional shares)'),
  ('w6-kids-011', 6, 'kids', 'You can start with $1', 'Many brokerages have no minimum, so you can start with just $1, and most stock trades are free now. You need the habit more than a big pile of money.', 'PTG Chapter 8 (no minimum; commission-free)'),
  ('w6-kids-012', 6, 'kids', 'What should you buy first?', 'For beginners, a broad index ETF is a popular first pick. One purchase gives you a little of hundreds of companies at once. Simple and safe.', 'PTG Chapter 8 (buy a broad index ETF first)'),
  ('w6-kids-013', 6, 'kids', 'Pick a trusted brokerage', 'Use a well-known, trusted brokerage like Fidelity, Schwab, or Vanguard. Steer clear of risky or too-good-to-be-true apps.', 'PTG Chapter 8 (reputable brokerages)'),
  ('w6-kids-014', 6, 'kids', 'First-trade checklist', 'Know why you are buying, decide how much, decide when you would sell, use only a little money, and make the plan with a grown-up first.', 'workbook ch7-8; textbook p181'),
  ('w6-kids-015', 6, 'kids', 'Practice before real money', 'Everyone makes mistakes while learning. That is why you practice with pretend money first, until you feel ready. Practice before we play.', 'workbook ch8; orientation deck House Rules #3')
insert into game_items (id, game, prompt, answer, why, source, ord) values
  ('tot-001', 'trend-or-trap', 'Every peak is higher than the last one, and every dip also lands higher than the dip before it.', 'CLIMBING', 'Higher highs and higher lows mean the buyers keep winning the war. That is an uptrend.', 'textbook p15', 1),
  ('tot-002', 'trend-or-trap', 'Each rally stops at a lower point than before, and each drop makes a new lower bottom.', 'FALLING', 'Lower highs and lower lows mean the sellers keep winning the war. That is a downtrend.', 'textbook p15', 2),
  ('tot-003', 'trend-or-trap', 'All morning there are far more buyers than sellers for the stock.', 'CLIMBING', 'More people on the buyers'' side of the rope pulls the price up.', 'textbook p11-12', 3),
  ('tot-004', 'trend-or-trap', 'A flood of sellers hits the stock and almost nobody wants to buy.', 'FALLING', 'More people on the sellers'' side of the rope pulls the price down.', 'textbook p11-12', 4),
  ('tot-005', 'trend-or-trap', 'The price drops to a support floor it has bounced off three times before, and buyers step in again.', 'CLIMBING', 'Support is a floor where the buyers grab the rope and pull the price back up.', 'textbook p98-99', 5),
  ('tot-006', 'trend-or-trap', 'The price rises to a resistance ceiling that has turned it away twice, and sellers show up again.', 'FALLING', 'Resistance is a ceiling where the sellers grab the rope and pull the price back down.', 'textbook p98-99', 6),
  ('tot-007', 'trend-or-trap', 'The 50-day moving average crosses above the 200-day moving average.', 'CLIMBING', 'That is a Golden Cross, a signal the buyers have taken over the war (bullish).', 'textbook p118', 7),
  ('tot-008', 'trend-or-trap', 'The 50-day moving average crosses below the 200-day moving average.', 'FALLING', 'That is a Death Cross, a signal the sellers have taken over the war (bearish).', 'textbook p118', 8),
  ('tot-009', 'trend-or-trap', 'The price pushes above a resistance ceiling on a huge surge of volume.', 'CLIMBING', 'The buyers broke through the ceiling with a big crowd behind them, so the move up is real.', 'textbook p138', 9),
  ('tot-010', 'trend-or-trap', 'The price cracks below a support floor on heavy selling volume.', 'FALLING', 'The sellers smashed through the floor with a big crowd behind them, so the move down is real.', 'textbook p117, p138', 10),
  ('tot-011', 'trend-or-trap', 'Three tall green candles appear back to back with small wicks.', 'CLIMBING', 'The green team (buyers) won three battles in a row, so the war is climbing.', 'workbook candle activity', 11),
  ('tot-012', 'trend-or-trap', 'Three tall red candles appear back to back with small wicks.', 'FALLING', 'The red team (sellers) won three battles in a row, so the war is falling.', 'workbook candle activity', 12),
  ('tot-013', 'trend-or-trap', 'RSI has dropped under 30, and then the price starts turning up as buyers return.', 'CLIMBING', 'An RSI under 30 means it got too cold; the buyers are grabbing the rope again for a bounce.', 'textbook p116', 13),
  ('tot-014', 'trend-or-trap', 'RSI has pushed over 70, the rally stalls, and the price begins to roll over.', 'FALLING', 'An RSI over 70 means it ran too hot; the buyers are tired and the sellers take the rope.', 'textbook p116', 14),
  ('tot-015', 'trend-or-trap', 'A head and shoulders top finishes and the price breaks below the neckline.', 'FALLING', 'Head and shoulders is a reversal shape; the war flips to the sellers.', 'textbook p107, p138', 15),
  ('tot-016', 'trend-or-trap', 'A double bottom forms and the price breaks up above the peak between the two lows.', 'CLIMBING', 'A double bottom is a reversal up; the buyers take back the rope.', 'textbook p138', 16),
  ('tot-017', 'trend-or-trap', 'The price pulls back to a rising trendline and bounces off it.', 'CLIMBING', 'The buyers defended the rising trendline, so they are still winning the war.', 'textbook p101-103', 17),
  ('tot-018', 'trend-or-trap', 'The price falls straight through a rising trendline it had respected for weeks.', 'FALLING', 'The buyers lost the trendline; the sellers have grabbed the rope.', 'textbook p103', 18),
  ('tot-019', 'trend-or-trap', 'Weekly closes read $50, then $55, then $58, then $62, then $66.', 'CLIMBING', 'Each week the buyers win, closing higher than the last. That is a steady uptrend.', 'workbook ch2 price sequence', 19),
  ('tot-020', 'trend-or-trap', 'Weekly closes read $80, then $75, then $72, then $68, then $64.', 'FALLING', 'Each week the sellers win, closing lower than the last. That is a steady downtrend.', 'workbook ch2 price sequence', 20),
  ('tot-021', 'trend-or-trap', 'The price goes quiet and squeezes into a tight range, then bursts upward on rising volume.', 'CLIMBING', 'After a quiet standoff, the buyers won with a big crowd behind them, so the price breaks up.', 'textbook p116, p138', 21),
  ('tot-022', 'trend-or-trap', 'Buyers keep making higher lows while sellers can''t force a new low.', 'CLIMBING', 'The buyers are winning more of the tug-of-war each round, so the trend favors up.', 'textbook p15, p101', 22),
  ('tot-023', 'trend-or-trap', 'A company you follow reports much better earnings than expected and buyers rush in.', 'CLIMBING', 'Great news sends a crowd to the buyers'' side of the rope, lifting the price.', 'textbook p73, p186', 23),
  ('tot-024', 'trend-or-trap', 'The price dips a little below support, then snaps right back up above it and rockets.', 'CLIMBING', 'That is ''the bait and the grab'': a quick dip to trick sellers, then the buyers grab the rope and run. (Preview of a Week-3 pro move.)', 'orientation deck LZ-9 (the bait & the grab); textbook p98-99', 24),
  ('cb-001', 'candle-battle', 'Opens near the bottom, climbs all day, and closes way up high with only tiny wicks.', 'GREEN TEAM', 'Close is far above the open, so the green team (buyers) won the battle big.', 'workbook candle activity', 1),
  ('cb-002', 'candle-battle', 'Opens near the top, slides down all day, and closes way down low with only tiny wicks.', 'RED TEAM', 'Close is far below the open, so the red team (sellers) won the battle big.', 'workbook candle activity', 2),
  ('cb-003', 'candle-battle', 'Opens low and closes a little higher, with a long lower wick where buyers pushed back up.', 'GREEN TEAM', 'Close is above the open, so the green team won; the long lower wick shows how far the fight swung before they took over.', 'workbook candle activity', 3),
  ('cb-004', 'candle-battle', 'Opens high, gets pushed down, and closes a bit lower, with a long upper wick where sellers rejected the highs.', 'RED TEAM', 'Close is below the open, so the red team won; the long upper wick shows the fight swung up first before sellers slapped it down.', 'workbook candle activity', 4),
  ('cb-005', 'candle-battle', 'A short green body with very long wicks on BOTH ends.', 'GREEN TEAM', 'It closed just above the open, so the green team barely won, but the long wicks mean the fight swung wildly both ways.', 'workbook candle activity', 5),
  ('cb-006', 'candle-battle', 'A short red body with very long wicks on both ends.', 'RED TEAM', 'It closed just below the open, so the red team barely won, and the long wicks show a wild, uncertain battle.', 'workbook candle activity', 6),
  ('cb-007', 'candle-battle', 'Opens at the low, buyers take over, and it closes right at the high with no upper wick at all.', 'GREEN TEAM', 'Closing at the very top with no upper wick means the green team controlled the whole battle.', 'textbook p94', 7),
  ('cb-008', 'candle-battle', 'Opens at the high, sellers take over, and it closes right at the low with no lower wick at all.', 'RED TEAM', 'Closing at the very bottom with no lower wick means the red team controlled the whole battle.', 'textbook p94', 8),
  ('cb-009', 'candle-battle', 'A tall green body: it opened at $50 and closed at $58.', 'GREEN TEAM', 'Close ($58) is well above the open ($50): a strong win for the green team.', 'textbook p94', 9),
  ('cb-010', 'candle-battle', 'A tall red body: it opened at $58 and closed at $50.', 'RED TEAM', 'Close ($50) is well below the open ($58): a strong win for the red team.', 'textbook p94', 10),
  ('cb-011', 'candle-battle', 'Opened at $30, dipped to $28, but buyers pushed it back to close at $31.', 'GREEN TEAM', 'The fight swung down to $28, but it closed ($31) above the open ($30), so the green team won.', 'textbook p94', 11),
  ('cb-012', 'candle-battle', 'Opened at $31, spiked to $33, but sellers dragged it back to close at $30.', 'RED TEAM', 'The fight swung up to $33, but it closed ($30) below the open ($31), so the red team won.', 'textbook p94', 12),
  ('cb-013', 'candle-battle', 'A small green body sitting on top of a very long lower wick (a hammer shape).', 'GREEN TEAM', 'It closed above the open, so the green team won; the long lower wick shows how far the fight swung down before buyers rescued it.', 'textbook p94', 13),
  ('cb-014', 'candle-battle', 'A small red body hanging under a very long upper wick (a shooting-star shape).', 'RED TEAM', 'It closed below the open, so the red team won; the long upper wick shows how far the fight swung up before sellers crushed it.', 'textbook p94', 14),
  ('cb-015', 'candle-battle', 'A big green candle that completely swallows the small red candle from the day before.', 'GREEN TEAM', 'A bullish engulfing candle closes above its open and overpowers yesterday''s battle: a strong green-team takeover.', 'textbook p94', 15),
  ('cb-016', 'candle-battle', 'A big red candle that completely swallows the small green candle from the day before.', 'RED TEAM', 'A bearish engulfing candle closes below its open and overpowers yesterday''s battle: a strong red-team takeover.', 'textbook p94', 16),
  ('cb-017', 'candle-battle', 'Opened at $100 and closed at $104 with small wicks.', 'GREEN TEAM', 'Close ($104) above open ($100): the green team took the battle.', 'textbook p94', 17),
  ('cb-018', 'candle-battle', 'Opened at $104 and closed at $99 with small wicks.', 'RED TEAM', 'Close ($99) below open ($104): the red team took the battle.', 'textbook p94', 18),
  ('cb-019', 'candle-battle', 'A long green body with a tiny upper wick and no lower wick.', 'GREEN TEAM', 'A long green body means the green team pulled the rope hard the whole battle.', 'textbook p94', 19),
  ('cb-020', 'candle-battle', 'A long red body with a tiny lower wick and no upper wick.', 'RED TEAM', 'A long red body means the red team pulled the rope hard the whole battle.', 'textbook p94', 20),
  ('cb-021', 'candle-battle', 'Opened at $45, buyers held it up all day, and it closed at $47.', 'GREEN TEAM', 'Close ($47) above open ($45): green team wins the battle.', 'textbook p94', 21),
  ('cb-022', 'candle-battle', 'Opened at $47, sellers pressed all day, and it closed at $45.', 'RED TEAM', 'Close ($45) below open ($47): red team wins the battle.', 'textbook p94', 22),
  ('cb-023', 'candle-battle', 'A medium green candle after three red days, closing above its open on rising volume.', 'GREEN TEAM', 'It closed above the open, so the green team won, and the bigger crowd hints the buyers may be turning the war.', 'textbook p94, p117', 23),
  ('cb-024', 'candle-battle', 'A medium red candle after three green days, closing below its open on rising volume.', 'RED TEAM', 'It closed below the open, so the red team won, and the bigger crowd hints the sellers may be turning the war.', 'textbook p94, p117', 24)
